import{_ as o,o as a,c as n,ah as A}from"./chunks/framework.BcMkjLiY.js";const r="/projects/TonyPi/en/latest/assets/image2.Bez43vxZ.webp",e="/projects/TonyPi/en/latest/assets/image3.BTu2ao7k.webp",i="/projects/TonyPi/en/latest/assets/image2.NlVSCS4p.webp",s="/projects/TonyPi/en/latest/assets/image2.NlVSCS4p.webp",l="/projects/TonyPi/en/latest/assets/image4.CeTM9Eag.webp",c="data:image/png;base64,",g="data:image/png;base64,",h="data:image/png;base64,",T=JSON.parse('{"title":"7. PC Software Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/10.pc_control_course.md","filePath":"docs/10.pc_control_course.md"}'),d={name:"docs/10.pc_control_course.md"};function p(f,t,C,b,u,m){return a(),n("div",null,[...t[0]||(t[0]=[A('<h1 id="_7-pc-software-control" tabindex="-1">7. PC Software Control <a class="header-anchor" href="#_7-pc-software-control" aria-label="Permalink to &quot;7. PC Software Control&quot;">​</a></h1><h2 id="_7-1-pc-software-operation" tabindex="-1">7.1 PC Software Operation <a class="header-anchor" href="#_7-1-pc-software-operation" aria-label="Permalink to &quot;7.1 PC Software Operation&quot;">​</a></h2><p>Please turn off the APP and VNC connection when run the PC software.</p><h3 id="_7-1-1-turn-on-pc-software" tabindex="-1">7.1.1 Turn on PC Software <a class="header-anchor" href="#_7-1-1-turn-on-pc-software" aria-label="Permalink to &quot;7.1.1 Turn on PC Software&quot;">​</a></h3><p>Extract the <a href="https://store.hiwonder.com.cn/docs/TonyPi/PC%E7%AB%AF%E8%BD%AF%E4%BB%B6/main.rar" target="_blank" rel="noreferrer">pc control software</a> to file under English path and then open the icon in the file. Please turn off firewall before opening the application.</p><img loading="lazy" height="280" width="302" class="common_img" src="'+r+'" style="width:80px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If the error message appears, the reason is that the folder is saved by the file contains the Chinese. Please place all files from the software in the English directory.</p></div><h3 id="_7-1-2-pc-software-connection" tabindex="-1">7.1.2 PC Software Connection <a class="header-anchor" href="#_7-1-2-pc-software-connection" aria-label="Permalink to &quot;7.1.2 PC Software Connection&quot;">​</a></h3><p>(1) Turn on the switch to start TonyPi.</p><p>(2) After turning on, Raspberry Pi will be in a AP hotspot mode and launch a Wi-Fi hotspot with a network named with the first letters &quot;<strong>HW</strong>&quot;.</p><img loading="lazy" height="420" width="352" class="common_img" src="'+e+'" style="width:300px;"><p>(3) Open PC software, click &quot;<strong>Scan</strong>&quot; and wait for a moment to receive the data as below picture.</p><p>(4) Click &quot;<strong>Connect</strong>&quot; after scanning.</p><img loading="lazy" height="761" width="724" src="'+i+'" class="common_img" style="width:500px;"><h2 id="_7-2-start-tonypi-with-pc-software" tabindex="-1">7.2 Start TonyPi with PC Software <a class="header-anchor" href="#_7-2-start-tonypi-with-pc-software" aria-label="Permalink to &quot;7.2 Start TonyPi with PC Software&quot;">​</a></h2><p>(1) After successful scanning, let&#39;s move to the device connection. Then the real-time returned screen will appear at the software.</p><img loading="lazy" height="761" width="724" class="common_img" src="'+s+'" style="width:500px;"><p>(2) Next, you can control the movement of the robot by clicking the motion buttons on the left side of the interface. The layout and functions of the main interface are as follows:</p><img loading="lazy" height="420" width="352" class="common_img" src="'+e+'" style="width:300px;"><p>(3) The functions of each area are as shown in the following table:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:center;">Function area</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="245" width="325" src="'+l+'" style="width:350px;"></td><td style="text-align:center;"><strong>Image feedback area</strong></td><td style="text-align:center;">Display the returned image</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="249" width="463" src="'+c+'" style="width:350px;"></td><td style="text-align:center;"><strong>Body control area</strong></td><td style="text-align:center;">TonyPi operation</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="155" width="245" src="'+g+'" style="width:350px;"></td><td style="text-align:center;"><strong>Rotation operation area</strong></td><td style="text-align:center;">Rotation operation</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="63" width="449" src="'+h+'" style="width:350px;"></td><td style="text-align:center;"><strong>Connection state area</strong></td><td style="text-align:center;">Scan, connect or turn off the launched hotspot</td></tr></tbody></table>',21)])])}const y=o(d,[["render",p]]);export{T as __pageData,y as default};
